import React from 'react';

import Geo from '@pohodnik/icons/svg/Geo/Geo';
import Pass from '@pohodnik/icons/svg/Geo/Pass';
import Peak from '@pohodnik/icons/svg/Geo/Peak';

import { ObstacleType } from '../../@types/obstacles.types';

export const ObstacleIcon: React.FC<{ type: ObstacleType }> = ({ type }) => {
  if (type === ObstacleType.Pass) return <Pass />;
  if (type === ObstacleType.Peak) return <Peak />;
  if (type === ObstacleType.Poi) return <Geo />;
};
